/* Defines x86 CPU feature bits. Feature comments from the C header describe
 * /proc/cpuinfo names and dependency-table requirements. */

pub const NCAPINTS: usize = 22; /* N 32-bit words worth of info */
pub const NBUGINTS: usize = 2;  /* N 32-bit bug flags */

macro_rules! feature { ($name:ident, $word:expr, $bit:expr) => { pub const $name: usize = $word * 32 + $bit; }; }
macro_rules! bug { ($name:ident, $index:expr) => { pub const $name: usize = NCAPINTS * 32 + $index; }; }

